      pStmt p
      wrap p, m0, "except"
    elif (p.tok.kind in {tkFinally}):
      expect p, tkFinally
      expect p, tkColon
      pStmt p
      wrap p, m0, "fin"
    elif (p.tok.kind in {tkElse}):
      expect p, tkElse
      expect p, tkColon
