    pTypeDesc p
    discardUnused m260
  else:
    emitEmpty p
  expect p, tkEquals
  pOptInd p
  pExpr p
  let m = m0
  fanOut p, m
  discardUnused m0

proc pConstant*(p: var Parser) =
  let m0 = mark(p)
