  elif (p.tok.kind in {tkAccent, tkSymbol}):
    pConstDef p
  else:
    error p, "expected alternative"
  discardUnused m261
  if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
    let m262 = mark(p)
    pPostExprBlocks p
    discardUnused m262
  pIndAndComment p
  discardUnused m0

