proc pSimpleStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk28):
    let m267 = mark(p)
    if (p.tok.kind in {tkReturn}):
      pReturnStmt p
    elif (p.tok.kind in {tkRaise}):
      pRaiseStmt p
    elif (p.tok.kind in {tkYield}):
      pYieldStmt p
    elif (p.tok.kind in {tkDiscard}):
      pDiscardStmt p
    elif (p.tok.kind in {tkBreak}):
      pBreakStmt p
    elif (p.tok.kind in {tkContinue}):
      pContinueStmt p
    elif (p.tok.kind in {tkCurlyDotLe}):
      pPragmaStmt p
    elif (p.tok.kind in {tkImport}):
      pImportStmt p
    elif (p.tok.kind in {tkExport}):
      pExportStmt p
    elif (p.tok.kind in {tkFrom}):
      pFromStmt p
    elif (p.tok.kind in {tkInclude}):
      pIncludeStmt p
    elif (p.tok.kind in {tkComment}):
      pCommentStmt p
    else:
      error p, "expected alternative"
    discardUnused m267
    if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
      let m268 = mark(p)
      pTrailComment p
      discardUnused m268
  else:
    pExprStmt p
    if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
      let m269 = mark(p)
      pTrailComment p
      discardUnused m269
  discardUnused m0

proc pComplexOrSimpleStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk29):
    let m270 = mark(p)
    if (p.tok.kind in {tkIf}):
      pIfStmt p
    elif (p.tok.kind in {tkWhen}):
      pWhenStmt p
    elif (p.tok.kind in {tkWhile}):
      pWhileStmt p
    elif (p.tok.kind in {tkTry}):
      pTryStmt p
    elif (p.tok.kind in {tkFor}):
      pForStmt p
    elif (p.tok.kind in {tkBlock}):
      pBlockStmt p
    elif (p.tok.kind in {tkStatic}):
      pStaticStmt p
    elif (p.tok.kind in {tkDefer}):
      pDeferStmt p
    elif (p.tok.kind in {tkAsm}):
      pAsmStmt p
    elif (p.tok.kind in {tkBind}):
      pBindStmt p
    elif (p.tok.kind in {tkMixin}):
      pMixinStmt p
    elif (p.tok.kind in {tkCase}):
      pCaseStmt p
    else:
      error p, "expected alternative"
    discardUnused m270
  elif (p.tok.kind in {tkExcept}):
    expect p, tkExcept
    emitEmpty p
    pColcom p
    pStmt p
    wrap p, m0, "except"
  elif (p.tok.kind in {tkFinally}):
    expect p, tkFinally
    pColcom p
    pStmt p
    wrap p, m0, "fin"
  elif (p.tok.kind in {tkProc}):
    expect p, tkProc
    pRoutine(p, "proc")
  elif (p.tok.kind in {tkMethod}):
    expect p, tkMethod
    pRoutine(p, "method")
  elif (p.tok.kind in {tkFunc}):
    expect p, tkFunc
    pRoutine(p, "func")
  elif (p.tok.kind in {tkIterator}):
    expect p, tkIterator
    pRoutine(p, "iterator")
  elif (p.tok.kind in {tkMacro}):
    expect p, tkMacro
    pRoutine(p, "macro")
  elif (p.tok.kind in {tkTemplate}):
    expect p, tkTemplate
    pRoutine(p, "template")
  elif (p.tok.kind in {tkConverter}):
    expect p, tkConverter
    pRoutine(p, "converter")
  elif (p.tok.kind in {tkType}):
    expect p, tkType
    if (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icNoInd, icGt}):
      pSection_typeDef p
    elif (p.tok.kind in {tkParLe}):
      expect p, tkParLe
      pPrimary(p, pmTypeDesc)
      expect p, tkParRi
      wrap p, m0, "typeof"
      var prec271 = getPrecedence(p)
      while prec271 >= -1 and indClass(p) == icNoInd:
        let assoc271 = (if isRightAssoc(p): 0 else: 1)
        insertLeafAt p, m0, p.tok.s
        getTok p
        pSimpleExpr(p, prec271 + assoc271, pmNormal)
        wrap p, m0, "infix"
        prec271 = getPrecedence(p)
      if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
        let m272 = mark(p)
        pPostExprBlocks p
        discardUnused m272
    else:
      error p, "expected complexOrSimpleStmt"
  elif (p.tok.kind in {tkConst}):
    pushSection p, "const"
    expect p, tkConst
    pSection_constant p
    popSection p
  elif (p.tok.kind in {tkLet}):
    pushSection p, "let"
    expect p, tkLet
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkVar}):
    pushSection p, "var"
    expect p, tkVar
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkUsing}):
    pushLastSection p
    expect p, tkUsing
    pSection_variable p
    popSection p
    wrap p, m0, "using"
  else:
    pSimpleStmt p
  discardUnused m0

proc pStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk8 and indClass(p) in {icGt}):
    pushInd p
    pComplexOrSimpleStmt p
    while (p.tok.kind in Tk8 and indClass(p) in {icEq}) or (p.tok.kind in {tkSemiColon}):
      let m273 = mark(p)
      let m274 = mark(p)
      if (p.tok.kind in Tk8 and indClass(p) in {icEq}):
        checkInd p, {icEq}
        pComplexOrSimpleStmt p
      elif (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
        if (p.tok.kind in Tk8 and indClass(p) in {icNoInd, icEq}):
          let m275 = mark(p)
          pOptSameInd p
          pComplexOrSimpleStmt p
          discardUnused m275
      else:
        error p, "expected alternative"
      discardUnused m274
      discardUnused m273
    popInd p
  elif (p.tok.kind in Tk21 and indClass(p) in {icNoInd, icLt, icEq}):
    pNotInd p
    let m276 = mark(p)
    pSimpleStmt p
    while (p.tok.kind in {tkSemiColon}):
      expect p, tkSemiColon
      pSimpleStmt p
    discardUnused m276
  else:
    error p, "expected stmt"
  discardUnused m0

proc pSection_typeDef*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
    let m277 = mark(p)
    pTrailComment p
    discardUnused m277
  let m278 = mark(p)
  if (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icGt}):
    pushInd p
    let m279 = mark(p)
    let m280 = mark(p)
    if (p.tok.kind in {tkAccent, tkSymbol}):
      pTypeDef p
    elif (p.tok.kind in {tkComment}):
      emitLeaf p            # COMMENT
    else:
      error p, "expected alternative"
    discardUnused m280
    while (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icEq}):
      checkInd p, {icEq}
      let m281 = mark(p)
      if (p.tok.kind in {tkAccent, tkSymbol}):
        pTypeDef p
      elif (p.tok.kind in {tkComment}):
        emitLeaf p            # COMMENT
      else:
        error p, "expected alternative"
      discardUnused m281
    if ((p.tok.kind in {tkAccent, tkComment, tkSymbol})) and indClass(p) == icGt:
      error p, "invalid indentation in section_typeDef"
    discardUnused m279
    popInd p
  elif (p.tok.kind in {tkAccent, tkSymbol} and indClass(p) in {icNoInd}):
    checkInd p, {icNoInd}
    pTypeDef p
  else:
    error p, "expected alternative"
  discardUnused m278
  discardUnused m0

